import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`parts-pricing-monitor`,heroTitle:`Monitor competitor parts pricing in minutes`,heroSubtitle:`Perplexity Computer analyzes your parts list, tracks competitor pricing across suppliers, and flags gaps and opportunities — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your parts list`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls`,inputFilePrefill:`Review the uploaded file and extract every part number, SKU, description, and current price listed. Then: 1) Search major online suppliers, distributors, and competitor catalogs to find current market pricing for each part. 2) Build a comparison matrix showing my price vs. each competitor's price for every part — including percentage differences and absolute gaps. 3) Flag parts where I'm priced more than 10% above the cheapest competitor and parts where I'm significantly below market. 4) Identify pricing trends — which parts are seeing price increases or decreases across the market. 5) Deliver a prioritized action report with specific repricing recommendations, margin impact estimates, and a summary dashboard I can share with my team.`,heroOverlaySteps:[`Extracting part numbers, SKUs, and current prices from your file`,`Searching suppliers and competitor catalogs for live pricing data`,`Building a price comparison matrix with gap analysis`,`Repricing recommendations and margin impact report — ready to review`],generatingSteps:[`Parsing the uploaded file to extract parts, SKUs, and your current pricing`,`Designing an agent to search competitor catalogs and supplier sites for live pricing`,`Configuring price comparison matrices, gap detection, and trend analysis`,`Setting up repricing recommendations and automated monitoring alerts`],featureSectionTitle:`From parts list to pricing intelligence`,featureCardTitles:[`Connects to your operations stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Airtable, Notion, Slack, Google Drive — Computer pipes pricing data and alerts straight into the tools your team already uses.`,`Price comparison matrices. Competitor gap analysis. Margin impact estimates. Repricing recommendations prioritized by revenue opportunity.`],capabilitySectionTitle:`Your pricing analyst, on autopilot`,capabilitySectionSubtitle:`Upload your parts list, step away, come back to a complete competitive pricing report.`,capabilityCards:[{title:`Price Benchmarking`,description:`Computer can search suppliers, distributors, and competitor catalogs — and map every part in your catalog against live market pricing.`},{title:`Gap Detection`,description:`Computer can flag parts where you're overpriced, underpriced, or missing from key supplier channels — with exact percentage gaps per competitor.`},{title:`Repricing Recommendations`,description:`Computer can generate prioritized repricing actions — estimated margin impact, competitive positioning, and suggested price points for every flagged part.`},{title:`Connect Your Tools`,description:`Computer can push pricing data to Google Sheets, Airtable, Notion, and Slack — build workflows across your entire procurement and sales stack.`},{title:`Remember & Learn`,description:`Computer can remember your parts catalog, competitor list, and historical pricing across sessions — so every report tracks trends over time.`},{title:`Monitor & Alert`,description:`Computer can re-check competitor pricing on a schedule and alert you when a rival undercuts you or market prices shift significantly.`}]});export{t as default};
